```vhdl
if push='1' and pop='0' and cnt < to_unsigned(4,3) then cnt <= cnt + 1;
elsif pop='1' and push='0' and cnt > 0 then cnt <= cnt - 1; end if;
-- ...
full  <= '1' when cnt = to_unsigned(4,3) else '0';
empty <= '1' when cnt = 0 else '0';
```
